INSERT OR REPLACE INTO LocalizedText (Language, Tag, Text) VALUES
    ('en_US', 'LOC_VICTORY_HEGEMONY_NAME', 'Hegemony Victory'),
    ('en_US', 'LOC_VICTORY_HEGEMONY_DESCRIPTION', 'To achieve a Hegemony Victory, take the lead in score. Surpass your rivals’ combined totals in military strength and in Food, Production, Science, Culture, and Faith per turn. Your net Gold per turn must also exceed their combined positive net income. Own more than half of the completed world wonders still standing and become suzerain of more than half of the city-states with a suzerain.'),
    ('en_US', 'LOC_VICTORY_HEGEMONY_BLURB', 'The winning civilization has united prosperity, knowledge, faith, and military might. Its wonders bear witness to an age of achievement, and city-states look to it for leadership. Its hegemony will shape the world for generations.'),
    ('zh_Hans_CN', 'LOC_VICTORY_HEGEMONY_NAME', '霸权胜利'),
    ('zh_Hans_CN', 'LOC_VICTORY_HEGEMONY_DESCRIPTION', '要取得霸权胜利，您的文明必须在总分上独占鳌头。军力以及每回合的食物、生产力、科技、文化和信仰，均须超过对手的相应合计。每回合的净金币收入也须超过对手的正净收入之和。您还须拥有过半数现存的已完工世界奇观，并成为过半数有宗主城邦的宗主。'),
    ('zh_Hans_CN', 'LOC_VICTORY_HEGEMONY_BLURB', '繁荣、知识、信仰和军力汇聚于这个获胜文明。宏伟的奇观见证它的盛世，众多城邦拥戴它为宗主。它的霸权将在未来数代塑造这个世界。');
